// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { Btn, DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, JSON_LINES, OUTPUTS } from './script'

const FACE = 232

const build: Build = ({ tl, q, qa, step, final, move, click, scramble, wait, cursorOut }) => {
  const target = (index: number) => {
    move('to')
    click('to')
    scramble('to-text', OUTPUTS[index].format, { at: '<', duration: 0.35 })
    tl.to(q('cube'), { rotationY: -90 * index, duration: 0.9, ease: 'power3.inOut' }, '<0.15')
    tl.fromTo(
      qa(`out-${index}`),
      { opacity: 0, x: 8 },
      { opacity: 1, x: 0, duration: 0.2, stagger: 0.04 },
      '-=0.35',
    )
  }

  step(0)
  tl.set(q('cube'), { z: -FACE / 2, rotationY: 0 }, 0)
  tl.fromTo(
    qa('in-line'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.2, stagger: 0.04 },
    0.3,
  )

  step(1, '+=0.3')
  move('convert')
  click('convert')
  tl.fromTo(
    qa('out-0'),
    { opacity: 0, x: 8 },
    { opacity: 1, x: 0, duration: 0.25, stagger: 0.06 },
    '<0.1',
  )

  step(2, '+=0.6')
  target(1)

  step(3, '+=0.6')
  target(2)
  wait(0.6)
  target(3)
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

function Select({ d, children }: { d?: string; children: string }) {
  return (
    <span
      data-d={d}
      className="flex h-7 w-24 items-center justify-between rounded-lg border border-line bg-canvas/80 px-2 text-[10px] text-ink"
    >
      <span data-d={d ? `${d}-text` : undefined}>{children}</span>
      <span className="text-muted">▾</span>
    </span>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Universal Converter turning one JSON array into CSV, XML, YAML and a Markdown table"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2.5">
          <div className="flex items-center gap-2">
            <Select>JSON</Select>
            <span className="text-[10px] text-muted">→</span>
            <Select d="to">CSV</Select>
            <Btn d="convert" primary>
              Convert
            </Btn>
          </div>
          <div className="grid min-h-0 flex-1 grid-cols-2 gap-2.5">
            <div className="rounded-xl border border-line bg-canvas/70 p-2.5">
              <p className="mb-1 text-[9px] uppercase tracking-[0.14em] text-muted">Input</p>
              <pre className="font-mono text-[9.5px] leading-[14px] text-ink-soft">
                {JSON_LINES.map((line, index) => (
                  <span key={index} data-d="in-line" className="block whitespace-pre">
                    {line}
                  </span>
                ))}
              </pre>
            </div>
            <div className="relative [perspective:900px]">
              <div
                data-d="cube"
                className="absolute inset-0 [transform-style:preserve-3d]"
                style={{ transform: `translateZ(-${FACE / 2}px)` }}
              >
                {OUTPUTS.map((output, index) => (
                  <div
                    key={output.format}
                    className="absolute inset-0 rounded-xl border border-[#60a5fa]/40 bg-[#0d121c] p-2.5 [backface-visibility:hidden]"
                    style={{ transform: `rotateY(${index * 90}deg) translateZ(${FACE / 2}px)` }}
                  >
                    <p className="mb-1 text-[9px] uppercase tracking-[0.14em] text-[#60a5fa]">
                      Output · {output.format}
                    </p>
                    <pre className="font-mono text-[9.5px] leading-[14px] text-ink-soft">
                      {output.lines.map((line, row) => (
                        <span
                          key={row}
                          data-d={`out-${index}`}
                          className="block whitespace-pre opacity-0"
                        >
                          {line}
                        </span>
                      ))}
                    </pre>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
